import { Group, Mesh, PlaneGeometry, CylinderGeometry, CircleGeometry, DirectionalLight, Color } from 'three/webgpu';
import { uv, mix, smoothstep, sub, float } from 'three/tsl';
import { gsap } from 'gsap';
import { orbit, depthRotate } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
    const { Group: THREEGroup } = ctx.THREE;

    // Root group (scenePosition applied by adapter)
    const root = new Group();

    // ---------- Backdrop Plane with Gradient ----------
    const bgGeom = new PlaneGeometry(7, 6);
    const yFlip = sub(float(1.0), uv().y); // 1 - uv.y to align 0 at top
    const gradColor = mix(
        mix(new Color('#0b0b10'), new Color('#101017'), smoothstep(0.0, 0.55, yFlip)),
        new Color('#16161d'),
        smoothstep(0.55, 1.0, yFlip)
    );
    const bgMat = new MeshBasicNodeMaterial({ colorNode: gradColor });
    const bgMesh = new Mesh(bgGeom, bgMat);
    bgMesh.position.set(0, 0, -2.5);
    root.add(bgMesh);

    // ---------- Plinth ----------
    const plinthGeom = new CylinderGeometry(1.4, 1.4, 0.25, 32);
    const plinthMat = new MeshStandardNodeMaterial({
        color: new Color('#14141a'),
        roughness: 0.7,
        metalness: 0.3
    });
    const plinth = new Mesh(plinthGeom, plinthMat);
    // Cylinder centered at its local origin; top at y = +0.125, we need top at -1.1
    plinth.position.set(0, -1.225, 0);
    root.add(plinth);

    // ---------- Contact Shadow ----------
    const shadowGeom = new CircleGeometry(1.6, 32);
    const shadowMat = new MeshBasicNodeMaterial({
        color: new Color(0x000000),
        transparent: true,
        opacity: 0.55,
        depthWrite: false
    });
    const shadow = new Mesh(shadowGeom, shadowMat);
    shadow.rotation.x = -Math.PI / 2; // face upward
    shadow.position.set(0, -1.1, 0);
    root.add(shadow);

    // ---------- Load Watch GLB ----------
    if (config.meshUrl) {
        ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
            const model = gltf.scene || gltf;
            root.add(model);
        });
    }

    // ---------- Text Content ----------
    const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
    const textGroup = new Group();
    root.add(textGroup);

    const paperColor = config.visualSpec?.colors?.paper ?? '#e8ecf2';
    const accentColor = config.visualSpec?.colors?.accent ?? '#ff2a38';

    const roleToOpts = {
        headline: { fontSize: 68, color: paperColor, align: 'center' },
        body: { fontSize: 26, color: paperColor, align: 'center' },
        caption: { fontSize: 18, color: paperColor, align: 'center' }
    };

    let yCursor = -1.5; // headline baseline
    for (const item of items) {
        const role = item.role ?? 'body';
        const opts = roleToOpts[role] || roleToOpts.body;
        const txtObj = ctx.fontAtlas.createText(item.text, {
            fontSize: opts.fontSize,
            color: opts.color,
            align: opts.align
        });
        txtObj.position.set(0, yCursor, 0);
        textGroup.add(txtObj);
        // advance cursor based on role sizes
        if (role === 'headline') yCursor -= 0.5; // space to body
        else if (role === 'body') yCursor -= 0.3; // space to caption
    }

    // ---------- Lights ----------
    const keyLight = new DirectionalLight('#ffffff', 1.2);
    keyLight.position.set(0.5, 0.8, 1);
    root.add(keyLight);

    const rimLight = new DirectionalLight('#ff2a38', 0.8);
    rimLight.position.set(-0.5, 0.0, 1);
    root.add(rimLight);

    // ---------- Cinematic Primitives ----------
    const primitiveInstances = [];
    const primitives = config.cinematicPrimitives ?? [];
    for (const prim of primitives) {
        const fn = ctx.primitives[prim.name];
        if (typeof fn === 'function') {
            const inst = fn(root, prim.params);
            primitiveInstances.push(inst);
        }
    }

    // ---------- GSAP Timelines (none directly added) ----------
    const timelines = [];

    // ---------- Cleanup ----------
    root.userData.handlers = {};
    root.userData.cleanup = () => {
        // Primitive cleanups
        for (const p of primitiveInstances) {
            if (p && typeof p.cleanup === 'function') p.cleanup();
        }
        // Dispose meshes, geometries, materials
        root.traverse((obj) => {
            if (obj.isMesh) {
                obj.geometry?.dispose?.();
                obj.material?.dispose?.();
            }
        });
        // Kill GSAP timelines
        for (const tl of timelines) {
            tl.kill();
        }
    };

    return root;
}
